.stats { display: flex; justify-content: center; flex-wrap: wrap; gap: 8px 24px; width: 100%; color: #b8bdd2; }
.stats p { margin: 0; }
.stats strong { color: #f4f6ff; font-variant-numeric: tabular-nums; }
.boardScroll, .reproductionPanel { max-width: 100%; }
.winBanner { display: flex; align-items: center; justify-content: center; flex-wrap: wrap; gap: 8px 16px; width: 100%; padding: 12px 16px; border: 1px solid #8bea7d; border-radius: 8px; color: #8bea7d; text-align: center; }
.winBanner strong { color: #f4f6ff; }
.winBanner.celebrate { animation: win-pulse 600ms ease-out 1; }
@keyframes win-pulse {
  0% { transform: scale(1); box-shadow: 0 0 0 0 rgb(139 234 125 / 35%); }
  45% { transform: scale(1.025); box-shadow: 0 0 24px 4px rgb(139 234 125 / 25%); }
  100% { transform: scale(1); box-shadow: 0 0 0 0 rgb(139 234 125 / 0%); }
}
.footerNote { margin: 24px 0 0; color: #b8bdd2; font-size: 14px; text-align: center; }

@media (prefers-reduced-motion: reduce) {
  .winBanner.celebrate { animation: none; }
}

@media (max-width: 480px) {
  .appShell { padding-top: 16px; }
  .gameHeader { margin-bottom: 16px; }
  .stats { gap: 8px 16px; }
  .dealControls { justify-content: center; }
}

/work/src/game/controls/DealControls.tsx.content:
import { BOARD_SIZES, type BoardSize } from "../board-code.ts";
import "./controls.css";

type DealControlsProps = {
  size: BoardSize;
  onChangeSize: (size: BoardSize) => void;
  onNewGame: () => void;
  onRestart: () => void;
};

export function DealControls({ size, onChangeSize, onNewGame, onRestart }: DealControlsProps) {
  return (
    <div className="dealControls">
      <label className="sizeControl">
        <span>Grid size</span>
        <select value={size} onChange={(event) => onChangeSize(Number(event.currentTarget.value) as BoardSize)}>
          {BOARD_SIZES.map((option) => <option key={option} value={option}>{option}x{option}</option>)}
        </select>
      </label>
      <button className="actionButton primaryAction" type="button" onClick={onNewGame}>New Game</button>
      <button className="actionButton" type="button" onClick={onRestart}>Restart</button>
    </div>
  );
}

/work/src/game/controls/ReproductionCont.content:
import type { Announcement, GameSession } from "../session/useGameSession.ts";
import "./controls.css";

type ReproductionControlsProps = Pick<GameSession,
  "status" | "announcement" | "boardCodeDraft" | "setBoardCodeDraft" | "snapshotDraft" |
  "setSnapshotDraft" | "loadBoard" | "exportSnapshot" | "loadSnapshot" | "paused"> & {
  onResume: () => void;
};

export function ReproductionControls(props: ReproductionControlsProps) {
  return (
    <details className="reproductionPanel">
      <summary>Reproduce a game</summary>
      <div className="reproductionContent">
        <div className="reproductionField">
          <label htmlFor="board-code">Board code</label>
          <div className="fieldActionRow">
            <input
              id="board-code"
              type="text"
              maxLength={32}
              spellCheck={false}
              value={props.boardCodeDraft}
              onChange={(event) => props.setBoardCodeDraft(event.currentTarget.value)}
            />
            <button className="actionButton" type="button" onClick={props.loadBoard}>Load board</button>
          </div>
        </div>
        <div className="reproductionField">
          <label htmlFor="snapshot-json">Snapshot JSON</label>
          <textarea
            id="snapshot-json"
            maxLength={65_536}
            spellCheck={false}
            rows={5}
            value={props.snapshotDraft}
            onChange={(event) => props.setSnapshotDraft(event.currentTarget.value)}
          />
          <div className="fieldActions">
            <button className="actionButton" type="button" onClick={props.exportSnapshot}>Export snapshot</button>
            <button className="actionButton" type="button" onClick={props.loadSnapshot}>Load snapshot</button>
            {props.paused && <button className="actionButton primaryAction" type="button" onClick={props.onResume}>Resume</button>}
          </div>
        </div>
        <p className="reproductionStatus" aria-hidden="true">{props.status}</p>
        <p key={props.announcement.id} className="screenReaderOnly" role="status" aria-live="polite" aria-atomic="true">
          {props.announcement.text}
        </p>
      </div>
    </details>
  );
}

