  const [boardCodeDraft, setBoardCodeDraft] = useState(game.board.boardCode);
  const [snapshotDraft, setSnapshotDraft] = useState("");
  const resetClock = useActiveClock(gameRef, pausedRef, setGame);

  const publish = useCallback((text: string, showStatus = false) => {
    announcementId.current += 1;
    setAnnouncement({ id: announcementId.current, text });
    if (showStatus) setStatus(text);
  }, []);

  const replaceGame = useCallback((next: GameState, codeDraft = next.board.boardCode, pause = false) => {
    gameRef.current = next;
    setGame(next);
    setBoardCodeDraft(codeDraft);
    setCelebration(false);
    pausedRef.current = pause;
    setPaused(pause);
    setResetToken((token) => token + 1);
    resetClock();
  }, [resetClock]);

  const activate = useCallback((index: number) => {
    const current = gameRef.current;
    if (pausedRef.current) return;
    if (!current.started) {
      resetClock();
    }
    const next = activateCard(current, index);
    if (next === current) return;
    gameRef.current = next;
    setGame(next);
    if (current.selection.kind === "one") {
      if (next.selection.kind === "mismatch") publish("No match. Cards close after a short pause.");
      else if (next.matched.length > current.matched.length) {
        if (isWon(next)) {
          publish(`Pair found. All pairs found in ${next.moves} moves and ${formatTime(next.elapsedMs)}.`);
          setCelebration(true);
          const score = saveBestScore(next.board.size, next.moves);
          if (score !== null) setBestScores((scores) => ({ ...scores, [next.board.size]: score }));
        } else {
          const pairs = matchedPairs(next);
          publish(`Pair found. ${pairs} ${pairs === 1 ? "pair matched." : "pairs matched."}`);
        }
      }
    }
  }, [publish, resetClock]);

  const newGame = useCallback(() => {
    setStatus("");
    const current = gameRef.current;
    replaceGame(freshGame(current.board.size, current.board.boardCode));
  }, [replaceGame]);

  const restart = useCallback(() => {
    setStatus("");
    const next = createGame(gameRef.current.board.boardCode);
    if (next) replaceGame(next);
  }, [replaceGame]);

  const changeSize = useCallback((size: BoardSize) => {
    savePreferredSize(size);
    setStatus("");
    replaceGame(freshGame(size));
  }, [replaceGame]);

  const loadBoard = useCallback(() => {
    const next = createGame(boardCodeDraft.trim());
    if (!next) {
      publish("Invalid board code.", true);
      return;
    }
    savePreferredSize(next.board.size);
    setStatus("");
    replaceGame(next);
    publish("Loaded board.", true);
  }, [boardCodeDraft, publish, replaceGame]);

  const exportSnapshot = useCallback(() => {
    setSnapshotDraft(encodeSnapshot(gameRef.current));
    setStatus("Snapshot exported.");
  }, []);

  const loadSnapshot = useCallback(() => {
    const next = decodeSnapshot(snapshotDraft);
    if (!next) {
      publish("Invalid snapshot.", true);
      return;
    }
    savePreferredSize(next.board.size);
    const complete = isWon(next);
    const pause = !complete;
    replaceGame(next, next.board.boardCode, pause);
    const message = complete ? "Loaded completed snapshot." : "Loaded snapshot. Select Resume to continue.";
    publish(message, true);
  }, [publish, replaceGame, snapshotDraft]);

  const resume = useCallback(() => {
    pausedRef.current = false;
    setPaused(false);
    resetClock();
  }, [resetClock]);

  return {
    game,
    best: bestScores[game.board.size],
    paused,
    status,
    announcement,
    celebration,
    resetToken,
    boardCodeDraft,
    setBoardCodeDraft,
    snapshotDraft,
    setSnapshotDraft,
    activate,
    newGame,
    restart,
    changeSize,
    loadBoard,
    exportSnapshot,
    loadSnapshot,
    resume,
  };
}
import type { Announcement, GameSession } from "../session/useGameSession.ts";
import "./controls.css";

type ReproductionControlsProps = Pick<GameSession,
  "status" | "announcement" | "boardCodeDraft" | "setBoardCodeDraft" | "snapshotDraft" |
  "setSnapshotDraft" | "loadBoard" | "exportSnapshot" | "loadSnapshot" | "paused"> & {
  onResume: () => void;
};

export function ReproductionControls(props: ReproductionControlsProps) {
  return (
    <>
      <details className="reproductionPanel">
        <summary>Reproduce a game</summary>
        <div className="reproductionContent">
          <div className="reproductionField">
            <label htmlFor="board-code">Board code</label>
            <div className="fieldActionRow">
              <input
                id="board-code"
                type="text"
                maxLength={32}
                spellCheck={false}
                value={props.boardCodeDraft}
                onChange={(event) => props.setBoardCodeDraft(event.currentTarget.value)}
              />
              <button className="actionButton" type="button" onClick={props.loadBoard}>Load board</button>
            </div>
          </div>
          <div className="reproductionField">
            <label htmlFor="snapshot-json">Snapshot JSON</label>
            <textarea
              id="snapshot-json"
              maxLength={65_536}
              spellCheck={false}
              rows={5}
              value={props.snapshotDraft}
              onChange={(event) => props.setSnapshotDraft(event.currentTarget.value)}
            />
            <div className="fieldActions">
              <button className="actionButton" type="button" onClick={props.exportSnapshot}>Export snapshot</button>
              <button className="actionButton" type="button" onClick={props.loadSnapshot}>Load snapshot</button>
              {props.paused && <button className="actionButton primaryAction" type="button" onClick={props.onResume}>Resume</button>}
            </div>
          </div>
          <p className="reproductionStatus" aria-hidden="true">{props.status}</p>
        </div>
      </details>
      <p key={props.announcement.id} className="screenReaderOnly" role="status" aria-live="polite" aria-atomic="true">
          {props.announcement.text}
      </p>
    </>
  );
}

